import type { Vec2 as Vec2Type, SimulationParams } from './types';

/**
 * Vector utility functions
 */
export const Vec2 = {
  /**
   * Calculate the magnitude (length) of a vector
   */
  magnitude(v: Vec2Type): number {
    return Math.sqrt(v.x * v.x + v.y * v.y);
  },

  /**
   * Add two vectors
   */
  add(a: Vec2Type, b: Vec2Type): Vec2Type {
    return { x: a.x + b.x, y: a.y + b.y };
  },

  /**
   * Subtract vector b from vector a
   */
  subtract(a: Vec2Type, b: Vec2Type): Vec2Type {
    return { x: a.x - b.x, y: a.y - b.y };
  },

  /**
   * Multiply vector by scalar
   */
  scale(v: Vec2Type, scalar: number): Vec2Type {
    return { x: v.x * scalar, y: v.y * scalar };
  },

  /**
   * Normalize vector to unit length
   */
  normalize(v: Vec2Type): Vec2Type {
    const mag = Vec2.magnitude(v);
    return mag > 0 ? { x: v.x / mag, y: v.y / mag } : { x: 0, y: 0 };
  }
};

/**
 * Calculate gravitational acceleration at a given position
 * a = -GM/r² * r̂
 *
 * @param position Position vector from planet center
 * @param params Simulation parameters
 * @returns Acceleration vector
 */
export function calculateGravitationalAcceleration(
  position: Vec2Type,
  params: SimulationParams
): Vec2Type {
  const r = Vec2.magnitude(position);

  // Avoid singularity at r = 0
  if (r < 1e-10) {
    return { x: 0, y: 0 };
  }

  // Acceleration magnitude: a = GM/r²
  const aMagnitude = (params.G * params.planetMass) / (r * r);

  // Direction: toward planet center (negative radial direction)
  const direction = Vec2.normalize(position);

  // a = -aMagnitude * r̂
  return Vec2.scale(direction, -aMagnitude);
}

/**
 * Calculate initial position on planet rim at given angle
 * @param _angle Launch angle in radians (0 = horizontal tangent, π/2 = vertical up)
 * @param radius Planet radius
 * @param altitude Altitude above planet surface
 * @returns Position vector from planet center
 */
export function calculateInitialPosition(_angle: number, radius: number, altitude: number = 0): Vec2Type {
  // Cannon is at the top of the planet (at 90° from horizontal)
  const cannonPositionAngle = Math.PI / 2; // Top of planet (12 o'clock position)
  // Total distance from planet center = radius + altitude
  const distanceFromCenter = radius + altitude;

  return {
    x: distanceFromCenter * Math.cos(cannonPositionAngle),
    y: distanceFromCenter * Math.sin(cannonPositionAngle)
  };
}

/**
 * Calculate initial velocity from launch angle and muzzle speed
 * @param angle Launch angle in radians (0 = horizontal, π/2 = vertical)
 * @param speed Muzzle speed
 * @param position Position on planet surface
 * @returns Velocity vector
 */
export function calculateInitialVelocity(
  angle: number,
  speed: number,
  position: Vec2Type
): Vec2Type {
  // For a cannon at the top (x ≈ 0, y > 0):
  // - angle = 0 means shooting tangentially (horizontally to the right, in +x direction)
  // - angle = π/2 means shooting radially outward (straight up, in +y direction)

  // Calculate the tangent direction (perpendicular to radial, clockwise for rightward motion)
  const radialDir = Vec2.normalize(position);
  const tangentDir = { x: radialDir.y, y: -radialDir.x };

  // Velocity is a combination of tangent and radial components
  const tangentComponent = Vec2.scale(tangentDir, speed * Math.cos(angle));
  const radialComponent = Vec2.scale(radialDir, speed * Math.sin(angle));

  return Vec2.add(tangentComponent, radialComponent);
}
