import type { Renderer } from './renderer';
import type { Vec2 } from '../simulation/types';

/**
 * Visual configuration for the projectile and its trace
 */
export interface ProjectileStyle {
  projectileColor: string;
  projectileRadius: number;
  traceColor: string;
  traceWidth: number;
  traceAlphaStart: number; // Alpha for newest trace point (active trail)
  traceAlphaEnd: number;   // Alpha for oldest trace point (active trail)
  persistentTraceAlpha: number; // Alpha for persistent trail
  persistentTraceWidth: number; // Width for persistent trail
}

/**
 * A point in the projectile's trajectory trace
 */
interface TracePoint {
  position: Vec2;
  timestamp: number;
}

/**
 * Renders the projectile and its fading trajectory trace
 */
export class ProjectileRenderer {
  private style: ProjectileStyle;
  private tracePoints: TracePoint[] = []; // Active comet trail (fading)
  private persistentTracePoints: TracePoint[] = []; // Complete trajectory (persistent)
  private maxTracePoints: number;

  constructor(style: ProjectileStyle, maxTracePoints: number = 500) {
    this.style = style;
    this.maxTracePoints = maxTracePoints;
  }

  /**
   * Add a new point to the trajectory trace
   */
  addTracePoint(position: Vec2, timestamp: number): void {
    const point = { position: { ...position }, timestamp };

    // Add to active comet trail
    this.tracePoints.push({ ...point });
    // Limit the number of active trace points
    if (this.tracePoints.length > this.maxTracePoints) {
      this.tracePoints.shift();
    }

    // Add to persistent trail (no limit, keeps entire trajectory)
    this.persistentTracePoints.push({ ...point });
  }

  /**
   * Clear the trajectory trace
   */
  clearTrace(): void {
    this.tracePoints = [];
    this.persistentTracePoints = [];
  }

  /**
   * Render the projectile and its trace
   * @param renderer Main renderer instance
   * @param currentPosition Current position of projectile (world coordinates)
   */
  render(renderer: Renderer, currentPosition: Vec2 | null): void {
    const ctx = renderer.getContext();

    // First, render the persistent trail (semi-transparent, shows complete path)
    if (this.persistentTracePoints.length > 1) {
      ctx.save();
      ctx.strokeStyle = this.addAlphaToColor(this.style.traceColor, this.style.persistentTraceAlpha);
      ctx.lineWidth = this.style.persistentTraceWidth;
      ctx.lineCap = 'round';
      ctx.lineJoin = 'round';

      ctx.beginPath();
      const firstPoint = renderer.worldToScreen(this.persistentTracePoints[0].position);
      ctx.moveTo(firstPoint.x, firstPoint.y);

      for (let i = 1; i < this.persistentTracePoints.length; i++) {
        const p = renderer.worldToScreen(this.persistentTracePoints[i].position);
        ctx.lineTo(p.x, p.y);
      }

      ctx.stroke();
      ctx.restore();
    }

    // Then, render the active comet trail with fading alpha (on top of persistent trail)
    if (this.tracePoints.length > 1) {
      ctx.save();
      ctx.strokeStyle = this.style.traceColor;
      ctx.lineWidth = this.style.traceWidth;
      ctx.lineCap = 'round';
      ctx.lineJoin = 'round';

      // Draw trace as a series of line segments with varying alpha
      for (let i = 0; i < this.tracePoints.length - 1; i++) {
        const t = i / (this.tracePoints.length - 1); // 0 (oldest) to 1 (newest)
        const alpha = this.style.traceAlphaEnd + t * (this.style.traceAlphaStart - this.style.traceAlphaEnd);

        const p1 = renderer.worldToScreen(this.tracePoints[i].position);
        const p2 = renderer.worldToScreen(this.tracePoints[i + 1].position);

        // Parse the trace color and add alpha
        const baseColor = this.style.traceColor;
        ctx.strokeStyle = this.addAlphaToColor(baseColor, alpha);

        ctx.beginPath();
        ctx.moveTo(p1.x, p1.y);
        ctx.lineTo(p2.x, p2.y);
        ctx.stroke();
      }

      ctx.restore();
    }

    // Finally, render the projectile itself
    if (currentPosition) {
      const screenPos = renderer.worldToScreen(currentPosition);

      ctx.save();
      ctx.fillStyle = this.style.projectileColor;
      ctx.beginPath();
      ctx.arc(screenPos.x, screenPos.y, this.style.projectileRadius, 0, Math.PI * 2);
      ctx.fill();
      ctx.restore();
    }
  }

  /**
   * Helper to add alpha to a color
   */
  private addAlphaToColor(color: string, alpha: number): string {
    // Simple implementation for hex colors
    if (color.startsWith('#')) {
      const r = parseInt(color.slice(1, 3), 16);
      const g = parseInt(color.slice(3, 5), 16);
      const b = parseInt(color.slice(5, 7), 16);
      return `rgba(${r}, ${g}, ${b}, ${alpha})`;
    }
    // If already rgba or rgb, just return as is (simplified)
    return color;
  }

  /**
   * Update the visual style
   */
  updateStyle(style: Partial<ProjectileStyle>): void {
    this.style = { ...this.style, ...style };
  }

  /**
   * Get the number of trace points currently stored
   */
  getTraceLength(): number {
    return this.tracePoints.length;
  }
}
