import type { Renderer } from './renderer';
import type { Vec2 } from '../simulation/types';

/**
 * Visual configuration for the cannon
 */
export interface CannonStyle {
  barrelColor: string;
  barrelWidth: number;
  barrelLength: number; // In world units
}

/**
 * Renders the cannon on the planet's surface
 */
export class CannonRenderer {
  private style: CannonStyle;

  constructor(style: CannonStyle) {
    this.style = style;
  }

  /**
   * Render the cannon at the given position and angle
   * @param renderer Main renderer instance
   * @param position Position on planet surface (world coordinates)
   * @param angle Launch angle in radians
   */
  render(renderer: Renderer, position: Vec2, angle: number): void {
    const ctx = renderer.getContext();
    const screenPos = renderer.worldToScreen(position);

    // Calculate the angle of the cannon barrel
    // The barrel should point in the direction of initial velocity
    // For a position on the right side: radial direction is position normalized
    // Tangent is perpendicular, and we add the launch angle

    const radialAngle = Math.atan2(position.y, position.x);
    const tangentAngle = radialAngle + Math.PI / 2; // 90° counterclockwise from radial
    const barrelAngle = tangentAngle + angle; // Add launch angle offset

    const barrelLength = renderer.worldToScreenDistance(this.style.barrelLength);

    ctx.save();
    ctx.translate(screenPos.x, screenPos.y);
    ctx.rotate(-barrelAngle); // Negative because canvas y-axis is flipped

    // Draw barrel as a thick line
    ctx.strokeStyle = this.style.barrelColor;
    ctx.lineWidth = this.style.barrelWidth;
    ctx.lineCap = 'round';
    ctx.beginPath();
    ctx.moveTo(0, 0);
    ctx.lineTo(barrelLength, 0);
    ctx.stroke();

    ctx.restore();
  }

  /**
   * Update the visual style
   */
  updateStyle(style: Partial<CannonStyle>): void {
    this.style = { ...this.style, ...style };
  }
}
