/**
 * Configuration for a slider control
 */
export interface SliderConfig {
  id: string;
  label: string;
  min: number;
  max: number;
  step: number;
  defaultValue: number;
  unit: string;
  /** Optional formatter for display value */
  formatter?: (value: number) => string;
  /** Group name for organizing sliders */
  group?: string;
}

/**
 * Manages the UI controls (sliders and buttons)
 */
export class Controls {
  private container: HTMLElement;
  private sliders: Map<string, HTMLInputElement> = new Map();
  private valueDisplays: Map<string, HTMLElement> = new Map();
  private launchButton: HTMLButtonElement | null = null;
  private resetButton: HTMLButtonElement | null = null;
  private listeners: {
    onLaunch?: () => void;
    onReset?: () => void;
    onSliderChange?: (id: string, value: number) => void;
  } = {};

  constructor(container: HTMLElement) {
    this.container = container;
  }

  /**
   * Create all the control elements
   */
  createControls(sliderConfigs: SliderConfig[]): void {
    // Create form element (base.css provides .form styles)
    const form = document.createElement('form');
    form.className = 'form';

    // Group sliders by their group property
    const groups = new Map<string, SliderConfig[]>();
    for (const config of sliderConfigs) {
      const groupName = config.group || 'default';
      if (!groups.has(groupName)) {
        groups.set(groupName, []);
      }
      groups.get(groupName)!.push(config);
    }

    // Create sliders organized by groups
    for (const [groupName, groupConfigs] of groups) {
      // Create a group container (using panel--muted for visual separation)
      const groupDiv = document.createElement('div');
      groupDiv.className = 'control-group';
      groupDiv.dataset.group = groupName;

      // Add group label if not default
      if (groupName !== 'default') {
        const groupLabel = document.createElement('h3');
        groupLabel.className = 'control-group__label';
        groupLabel.textContent = groupName;
        groupDiv.appendChild(groupLabel);
      }

      // Add sliders to group
      for (const config of groupConfigs) {
        const sliderControl = this.createSlider(config);
        groupDiv.appendChild(sliderControl);
      }

      form.appendChild(groupDiv);
    }

    // Create buttons (using base.css .row and .btn classes)
    const buttonsDiv = document.createElement('div');
    buttonsDiv.className = 'row mt-3';

    this.launchButton = document.createElement('button');
    this.launchButton.className = 'btn btn--primary';
    this.launchButton.type = 'button';
    this.launchButton.textContent = 'Launch';
    this.launchButton.addEventListener('click', () => {
      if (this.listeners.onLaunch) {
        this.listeners.onLaunch();
      }
    });

    this.resetButton = document.createElement('button');
    this.resetButton.className = 'btn btn--secondary';
    this.resetButton.type = 'button';
    this.resetButton.textContent = 'Reset';
    this.resetButton.addEventListener('click', () => {
      if (this.listeners.onReset) {
        this.listeners.onReset();
      }
    });

    buttonsDiv.appendChild(this.launchButton);
    buttonsDiv.appendChild(this.resetButton);

    form.appendChild(buttonsDiv);

    this.container.appendChild(form);
  }

  /**
   * Create a single slider control with label and value display
   */
  private createSlider(config: SliderConfig): HTMLElement {
    // Use base.css .control class
    const control = document.createElement('div');
    control.className = 'control';

    // Label and value display on same line (using .control__row from base.css)
    const row = document.createElement('div');
    row.className = 'control__row';

    const label = document.createElement('label');
    label.className = 'control__label';
    label.htmlFor = config.id;
    label.textContent = config.label;

    const valueDisplay = document.createElement('span');
    valueDisplay.className = 'control__value';
    const formattedValue = config.formatter
      ? config.formatter(config.defaultValue)
      : config.defaultValue.toFixed(this.getDecimalPlaces(config.step));
    valueDisplay.textContent = `${formattedValue} ${config.unit}`;
    this.valueDisplays.set(config.id, valueDisplay);

    row.appendChild(label);
    row.appendChild(valueDisplay);

    // Slider input (base.css provides input[type="range"] styling)
    const slider = document.createElement('input');
    slider.type = 'range';
    slider.id = config.id;
    slider.min = config.min.toString();
    slider.max = config.max.toString();
    slider.step = config.step.toString();
    slider.value = config.defaultValue.toString();

    slider.addEventListener('input', (e) => {
      const value = parseFloat((e.target as HTMLInputElement).value);
      const formatted = config.formatter
        ? config.formatter(value)
        : value.toFixed(this.getDecimalPlaces(config.step));
      valueDisplay.textContent = `${formatted} ${config.unit}`;

      if (this.listeners.onSliderChange) {
        this.listeners.onSliderChange(config.id, value);
      }
    });

    this.sliders.set(config.id, slider);

    control.appendChild(row);
    control.appendChild(slider);

    return control;
  }

  /**
   * Helper to determine decimal places from step value
   */
  private getDecimalPlaces(step: number): number {
    const stepStr = step.toString();
    if (stepStr.includes('.')) {
      return stepStr.split('.')[1].length;
    }
    return 0;
  }

  /**
   * Get the current value of a slider
   */
  getSliderValue(id: string): number | null {
    const slider = this.sliders.get(id);
    return slider ? parseFloat(slider.value) : null;
  }

  /**
   * Set the value of a slider
   */
  setSliderValue(id: string, value: number): void {
    const slider = this.sliders.get(id);
    if (slider) {
      slider.value = value.toString();
      slider.dispatchEvent(new Event('input'));
    }
  }

  /**
   * Enable or disable the launch button
   */
  setLaunchEnabled(enabled: boolean): void {
    if (this.launchButton) {
      this.launchButton.disabled = !enabled;
    }
  }

  /**
   * Enable or disable the reset button
   */
  setResetEnabled(enabled: boolean): void {
    if (this.resetButton) {
      this.resetButton.disabled = !enabled;
    }
  }

  /**
   * Enable or disable all sliders
   */
  setSlidersEnabled(enabled: boolean): void {
    this.sliders.forEach((slider) => {
      slider.disabled = !enabled;
    });
  }

  /**
   * Enable or disable specific sliders by their IDs
   */
  setSliderEnabled(id: string, enabled: boolean): void {
    const slider = this.sliders.get(id);
    if (slider) {
      slider.disabled = !enabled;
    }
  }

  /**
   * Enable or disable multiple sliders by their IDs
   */
  setSlidersEnabledByIds(ids: string[], enabled: boolean): void {
    ids.forEach(id => this.setSliderEnabled(id, enabled));
  }

  /**
   * Set event listeners
   */
  on(event: 'launch' | 'reset', callback: () => void): void;
  on(event: 'sliderChange', callback: (id: string, value: number) => void): void;
  on(event: string, callback: any): void {
    if (event === 'launch') {
      this.listeners.onLaunch = callback;
    } else if (event === 'reset') {
      this.listeners.onReset = callback;
    } else if (event === 'sliderChange') {
      this.listeners.onSliderChange = callback;
    }
  }
}
